// Generated by node scripts/build-posts.mjs. Edit the source files, then rebuild.
(() => {
  'use strict';
  const files = {"data/resources.json":"{\n  \"embedded\": [\n    {\n      \"title\": \"Arduino 官网\",\n      \"description\": \"Arduino 官方首页：开发板、软件与社区入口。\",\n      \"url\": \"https://www.arduino.cc/\",\n      \"tag\": \"官方网站\"\n    },\n    {\n      \"title\": \"Arduino 官方文档\",\n      \"description\": \"开发板资料、参考文档与入门示例。\",\n      \"url\": \"https://docs.arduino.cc/\",\n      \"tag\": \"官方入口\"\n    }\n  ],\n  \"english\": []\n}\n","projects/heart-matrix/heart_matrix/heart_matrix.ino":"/*\n *  ------------------------------------------------------------\n *   爱心点阵 · 你的第一个 Arduino 项目\n *  ------------------------------------------------------------\n *   硬件：Arduino UNO + 8×32 MAX7219 点阵（4 片 8×8 串起来）\n *   接线：VCC -> 5V    GND -> GND    DIN -> D11\n *         CS  -> D10   CLK -> D13\n *\n *   用法：插上 USB -> 选好 Arduino Uno 和端口 -> 点“上传”。\n *        不需要安装任何库，代码会自己驱动点阵。\n *\n *   上电后先全亮 1 秒（自检：四片都亮 = 接线成功），\n *   然后爱心会一直亮着，只让亮度跟着心跳起伏。\n *  ------------------------------------------------------------\n */\n\n#include \u003cSPI.h>\n\n// ===== 只有这两行可能需要你改（画面方向不对的时候）=====\n#define FLIP_X 0          // 左右镜像：画面左右反了改成 1\n#define FLIP_Y 0          // 上下颠倒：爱心变成“黑桃”改成 1\n\n// ===== 两个好玩的旋钮 =====\n#define BEAT_MS      1100 // 一次心跳多少毫秒：改小跳得快，改大更平静\n#define BRIGHT_SCALE 100  // 整体亮度百分比：觉得刺眼就改成 60\n\nconst uint8_t PIN_CS = 10;        // CS / LOAD 接 D10\nconst uint8_t CHIPS  = 4;         // 4 片 8×8\nconst uint8_t WIDTH  = CHIPS * 8; // 一共 32 列\n\nuint8_t canvas[WIDTH];            // 画布：一列一个字节，bit0 = 最上面那颗灯\n\n// ------------------------------------------------------------------\n//  爱心图案：'#' 是亮，'.' 是灭，一共 8 行、每行 32 个字符。\n//  想换个图案？直接改这块字符画就行，一个字符对一颗灯。\n// ------------------------------------------------------------------\nconst char *HEART[8] = {\n  \"............###..###............\",\n  \"...........####..####...........\",\n  \"..........############..........\",\n  \"..........############..........\",\n  \"...........##########...........\",\n  \"............########............\",\n  \".............######.............\",\n  \"...............##...............\",\n};\n\n// ------------------------------------------------------------------\n//  下面是可以先跳过的部分：怎么跟 MAX7219 说话\n// ------------------------------------------------------------------\n\n// 给第 chip 片（0 是最靠近 DIN 的那片）的某个寄存器写一个字节。\n// 点阵是串联的，所以每次要把 4 片都“喂”一遍，其余的喂 0x00（空操作）。\nvoid maxWrite(uint8_t chip, uint8_t reg, uint8_t value) {\n  digitalWrite(PIN_CS, LOW);\n  for (int8_t i = CHIPS - 1; i >= 0; i--) {\n    if (i == chip) {\n      SPI.transfer(reg);\n      SPI.transfer(value);\n    } else {\n      SPI.transfer(0x00);\n      SPI.transfer(0x00);\n    }\n  }\n  digitalWrite(PIN_CS, HIGH);\n}\n\nvoid maxSetup() {\n  for (uint8_t c = 0; c \u003c CHIPS; c++) {\n    maxWrite(c, 0x0F, 0x00);      // 关掉测试模式\n    maxWrite(c, 0x0B, 0x07);      // 8 行全用\n    maxWrite(c, 0x09, 0x00);      // 不译码（点阵必须这样）\n    maxWrite(c, 0x0A, 0x03);      // 初始亮度\n    maxWrite(c, 0x0C, 0x01);      // 开显示\n  }\n}\n\n// 把画布送到点阵上。\n//\n// 【重要】这块 8×32 点阵是“转置”接法的：每一片的 8 个寄存器\n// （0x01~0x08）对应的是 8 行，不是 8 列；每个字节的 8 个 bit 对应 8 列。\n// 所以发数据前要把图像转置一下，否则爱心会被切成左右两块。\nvoid show(uint8_t level) {\n  level = (uint16_t)level * BRIGHT_SCALE / 100;   // 应用亮度旋钮\n  if (level > 15) level = 15;\n\n  for (uint8_t c = 0; c \u003c CHIPS; c++) {\n    maxWrite(c, 0x0A, level);                     // 这一片的亮度\n\n    for (uint8_t r = 0; r \u003c 8; r++) {             // 第 r 行\n      uint8_t bits = 0;\n      for (uint8_t b = 0; b \u003c 8; b++) {           // 第 b 列\n        uint8_t rr = FLIP_Y ? (7 - r) : r;        // 上下颠倒\n        uint8_t bb = FLIP_X ? (7 - b) : b;        // 左右镜像\n        if (canvas[c * 8 + bb] & (1 \u003c\u003c rr)) bits |= (1 \u003c\u003c b);\n      }\n      maxWrite(c, r + 1, bits);                   // 0x01~0x08 就是第 1~8 行\n    }\n  }\n}\n\n// 把一张 8 行的字符画刷进画布\nvoid drawHeart(const char *art[8]) {\n  memset(canvas, 0, WIDTH);\n  for (uint8_t y = 0; y \u003c 8; y++) {\n    for (uint8_t x = 0; x \u003c WIDTH; x++) {\n      if (art[y][x] == '#') canvas[x] |= (1 \u003c\u003c y);\n    }\n  }\n}\n\n// 上电自检：全部点亮 1 秒。四片都亮，就说明接线和供电都没问题。\nvoid selfTest() {\n  memset(canvas, 0xFF, WIDTH);\n  show(6);\n  delay(1000);\n  memset(canvas, 0x00, WIDTH);\n  show(0);\n  delay(150);\n}\n\n// ------------------------------------------------------------------\n//  setup / loop\n// ------------------------------------------------------------------\nvoid setup() {\n  pinMode(PIN_CS, OUTPUT);\n  digitalWrite(PIN_CS, HIGH);\n\n  SPI.begin();\n  SPI.setBitOrder(MSBFIRST);\n  SPI.setDataMode(SPI_MODE0);\n  SPI.setClockDivider(SPI_CLOCK_DIV4);   // 4 MHz，MAX7219 吃得下\n\n  maxSetup();\n  selfTest();\n\n  drawHeart(HEART);   // 爱心画一次，之后循环里只改亮度\n}\n\nvoid loop() {\n  uint16_t t = millis() % BEAT_MS;   // 0 ~ BEAT_MS 之间循环\n  uint8_t  level;\n\n  if (t \u003c 220) {                     // 咚：最亮，然后快速回落\n    level = 15 - (uint8_t)((uint32_t)t * 8 / 220);          // 15 -> 7\n  } else if (t \u003c 340) {              // 稍停一下\n    level = 7;\n  } else if (t \u003c 560) {              // 哒：第二下，弱一点，慢一点回落\n    level = 12 - (uint8_t)((uint32_t)(t - 340) * 6 / 220);  // 12 -> 6\n  } else {                           // 安静：也保持能看清\n    level = 5;\n  }\n\n  show(level);\n  delay(15);\n}\n","posts/2026-11-25-heart-matrix-troubleshooting.md":"---\ntitle: \"爱心点阵排错笔记：灯不对的时候看这里\"\ndate: 2026-11-25\nparent: 2026-11-25-heart-matrix\ntags: [\"Arduino\", \"MAX7219\", \"排错笔记\"]\nsummary: \"整理自我的 notes/02-troubleshooting.md：按现象检查供电、通信、方向、映射与上传问题。\"\ncover: \"./projects/heart-matrix/preview.png\"\n---\n\n> 来源：我的项目笔记 `notes/02-troubleshooting.md`。网页精简了重复内容，把原文中仅凭现象就下结论的地方改为可逐项验证的排查步骤。\n\n[查看完整原始笔记](./projects/heart-matrix/notes/02-troubleshooting.md) · [阅读我的源码](./arduino-viewer.html?example=heart-matrix) · [完整项目记录](./blog.html#post/2026-11-25-heart-matrix)\n\n## 先记住：一次只改一个地方\n\n把“应该出现什么”“实际出现什么”“这次改了什么”写在一起。按供电与接线、通信与级联、方向、图案映射的顺序缩小范围；不要同时改电线、图案和程序。\n\n## 1. 完全不亮，或只有部分模块亮\n\n| 现象 | 下一步检查 | 暂时不能下的结论 |\n| --- | --- | --- |\n| 全亮自检没有出现 | 断电核对 VCC、GND、输入端及信号线；确认程序已上传 | 不能只凭全黑认定电源坏了 |\n| UNO 电源灯亮，点阵黑 | 检查模块是否获得正确供电，再核对 DIN、CLK、CS | 板子亮灯不代表模块通信正常 |\n| 前几片亮、后几片黑 | 检查 DOUT→DIN 级联、连接、供电和 `CHIPS = 4` | 不直接判定某片损坏 |\n| 暗、闪烁、反复重启 | 检查接触、短路、供电能力，再降低亮度验证 | 不用固定电流估算代替实际检查 |\n\n改线前断电。外部电源按模块和开发板规格连接、共地，避免向 USB 回灌。拔掉数据线后“是否全黑”不能作为供电正常的充分证据。\n\n## 2. 形状对，方向不对\n\n上下颠倒时，可以测试 `FLIP_Y`。左右方向则要区分“每片内部的列方向”和“四片的排列顺序”。当前源码中的 `FLIP_X` 只改变每片内部的列方向，没有反转四片的顺序。\n\n爱心左右对称，不适合单独验证左右映射。用位置明确的不对称标记，例如预期位于 `(1, 2)` 的亮点，再逐片对照实际位置。\n\n## 3. 两块亮斑，不像爱心\n\n这是原项目的主要问题：中间两片亮了，但左右两部分形状不符合预期。调亮度、缩窄图案、检查接缝，都没有直接解决它。\n\n最终修复集中在 `show()`：软件按列存像素，发送前需要重新组装模块所需的行数据。\n\n```cpp\nfor (uint8_t r = 0; r \u003c 8; r++) {\n  uint8_t bits = 0;\n  for (uint8_t b = 0; b \u003c 8; b++) {\n    if (canvas[c * 8 + b] & (1 \u003c\u003c r)) bits |= (1 \u003c\u003c b);\n  }\n  maxWrite(c, r + 1, bits);\n}\n```\n\n用预期坐标和实测坐标来验证修复。照片里的形状还会受到透视、曝光和拍摄角度影响，不能只凭“左右两块方向相反”就唯一确定原因。\n\n原文提到 L 形测试的局限：**是否能识别转置，要看具体图形是否在该变换下保持不变。** 不能把所有 L 形都归为“测不出来”；主对角线也不能单独排除转置。\n\n## 4. 偏移、缺灯\n\n- 位置偏移：检查字符画每行是否都是 32 个字符；爱心最宽 12 列的那一行，两侧各有 10 个 `.`。\n- 固定位置不亮：对比全亮测试、单点测试和目标图案，继续排查写入地址、接线与器件；不要一次观察就判定 LED 损坏。\n- 全亮正常但图案不对：优先核对行列、片序和方向，不能把全亮当作映射正确的证明。\n\n## 5. 编译或上传失败\n\n| 提示 | 先检查什么 |\n| --- | --- |\n| 找不到串口 | USB 数据线、实际端口、驱动；驱动型号取决于板上的 USB 转串口芯片 |\n| `ser_open(): can't open device` | 端口是否存在、是否被串口监视器或其他程序占用 |\n| `stk500_recv()` | 板型、端口、连接和复位等可能原因 |\n| `was not declared` | 拼写、作用域、声明和完整报错上下文 |\n| `expected ';'` | 报错行及其前面的语句 |\n\n把完整错误信息保存下来。网站只展示源码，本次导入没有替你重新编译或烧录。\n\n## 一分钟自查\n\n- 电源与引脚已按模块规格核对，改线时已断电。\n- UNO R3 的 DIN→D11、CS→D10、CLK→D13，GND 共地。\n- `CHIPS = 4`，字符画八行、每行 32 个字符。\n- Arduino IDE 选择实际开发板和串口。\n- 记录了本次唯一改动，以及修改前后的现象。\n\n这份笔记最值得保留的方法是：**“哪一颗灯不对”，比“看起来不对”更容易找到答案。**\n","posts/2026-11-25-heart-matrix-learning.md":"---\ntitle: \"爱心点阵学习笔记：从一块点阵开始\"\ndate: 2026-11-25\nparent: 2026-11-25-heart-matrix\ntags: [\"Arduino\", \"MAX7219\", \"学习笔记\"]\nsummary: \"整理自我的 notes/01-learning-notes.md：五根线、SPI、寄存器、位运算与心跳动画。\"\ncover: \"./projects/heart-matrix/preview.png\"\n---\n\n> 来源：我的项目笔记 `notes/01-learning-notes.md`。这是精简整理版，保留原文的学习顺序和核心代码，并校正级联、转置与时间线的表述。\n\n[查看完整原始笔记](./projects/heart-matrix/notes/01-learning-notes.md) · [阅读我的完整源码](./arduino-viewer.html?example=heart-matrix) · [看心跳效果](./projects/heart-matrix/index.html)\n\n## 1. 五根线，为什么能控制 256 颗灯？\n\n8×32 点阵由四片 8×8 模块组成，每片背后是一颗 MAX7219。它负责保存显示数据、扫描 LED、调节亮度。Arduino 负责告诉它“哪些灯亮”和“有多亮”。\n\n| 接线 | UNO R3 引脚 | 通俗解释 |\n| --- | --- | --- |\n| VCC | 5V | 按模块规格供电 |\n| GND | GND | 共地，作为信号的参考 |\n| DIN | D11 | 数据一位一位进入 |\n| CLK | D13 | 告诉芯片什么时候读取数据 |\n| CS / LOAD | D10 | 拉低传输，拉高锁存这一组数据 |\n\n项目使用 Arduino 内置 SPI 库，不额外安装第三方点阵库。改线前断电，核对模块电压、极性和引脚。\n\n## 2. 寄存器：给芯片的小格子写内容\n\n每条指令有两个字节：一个说明写到哪里，一个说明写什么。\n\n| 地址 | 在项目中的用途 |\n| --- | --- |\n| 0x0C | 显示开关 |\n| 0x0A | 亮度，取值 0–15 |\n| 0x0B | 扫描范围，写 7 表示使用八条扫描线 |\n| 0x09 | 关闭数字译码，使用点阵模式 |\n| 0x0F | 关闭显示测试模式 |\n| 0x01–0x08 | 八组显示数据，物理方向取决于模块接线 |\n\n`maxSetup()` 就是在给各片芯片设置这些参数。\n\n## 3. 四片级联：像一条传送带\n\n先发送的数据会向更远的芯片移动。本项目每次拉低 CS 后发送四组“地址 + 数据”，最后拉高 CS；目标芯片得到有效指令，其余芯片得到空操作。\n\n```cpp\nfor (int8_t i = CHIPS - 1; i >= 0; i--) {\n  if (i == chip) { SPI.transfer(reg); SPI.transfer(value); }\n  else { SPI.transfer(0x00); SPI.transfer(0x00); }\n}\n```\n\n这里每次都发送四组，不是“写第几片就只发送几组”。芯片顺序和整幅图像的左右方向要分别核对。\n\n## 4. 一个字节，存八颗灯\n\n`canvas[32]` 是软件画布：一列一个字节，每一位代表该列的一颗灯。32 列只需要 32 字节。\n\n```cpp\ncanvas[x] |= (1 \u003c\u003c y);      // 把第 y 位设为 1\ncanvas[x] &= ~(1 \u003c\u003c y);     // 把第 y 位设为 0\nif (canvas[x] & (1 \u003c\u003c y))   // 判断这一位是否为 1\n```\n\n字符画里的 `art[y][x]` 是“第 y 行、第 x 列”。`drawHeart()` 把字符 `#` 转成画布中对应的位。\n\n## 5. 画布和模块的坐标要对上\n\n软件按列存储，并不意味着模块也按列解释数据。原项目最终通过 `show()` 把每一列的位重新组成一行，再发送给对应的显示寄存器。\n\n```cpp\nfor (uint8_t r = 0; r \u003c 8; r++) {\n  uint8_t bits = 0;\n  for (uint8_t b = 0; b \u003c 8; b++) {\n    if (canvas[c * 8 + b] & (1 \u003c\u003c r)) bits |= (1 \u003c\u003c b);\n  }\n  maxWrite(c, r + 1, bits);\n}\n```\n\n这段是核心映射示意；完整源码还包含方向开关。**转置是行列互换，不等同于旋转 90°。** 也不能仅凭亮斑外形断定某一种映射错误。\n\n## 6. 爱心没换形状，变的是亮度\n\n字符画只在 `setup()` 中写入一次。之后用 `millis() % 1100` 计算当前处于心跳周期的哪一段。\n\n| 时间段 | 当前代码的亮度变化 |\n| --- | --- |\n| 0–220 ms | 从 15 向 7 回落，“咚” |\n| 220–340 ms | 保持 7，短暂停顿 |\n| 340–560 ms | 从 12 向 6 回落，“哒” |\n| 560–1100 ms | 保持 5，安静但仍可见 |\n\n原笔记使用了“非阻塞的雏形”这个说法。准确地说，程序已经用时间计算动画阶段，但 `loop()` 里仍有 `delay(15)`，并不是完全非阻塞。\n\n## 7. 把程序看成五件小事\n\n```text\nsetup()：初始化 SPI → 配置 MAX7219 → 全亮自检 → 写入爱心\nloop() ：计算当前阶段 → 设置亮度并刷新显示 → 等待 15 ms\n```\n\n全亮自检用于初步检查显示链路。核对行列映射时，选择位置已知、转置后会发生变化的标记；主对角线本身对称，不能单独用它排除转置问题。\n\n## 8. 留给下一次的练习\n\n- 只改字符画，观察哪一颗灯变化。\n- 只改 `BEAT_MS`，感受心跳周期的差别。\n- 再尝试按键、光敏传感器或滚动字幕，每次只引入一个新知识点。\n\n这些是原笔记里的后续学习方向，不代表已经完成的项目。先把这颗爱心讲明白，再做下一步。\n","posts/2026-11-25-heart-matrix.md":"---\ntitle: \"我的第一个嵌入式项目：爱心点阵\"\ndate: 2026-11-25\ntags: [\"Arduino\", \"MAX7219\", \"项目记录\"]\nsummary: \"整理自我的 notes/03-project-log.md：保留时间线、走过的弯路，以及最后的行列映射修复。\"\ncover: \"./projects/heart-matrix/preview.png\"\n---\n\n> 来源：我的项目笔记 `notes/03-project-log.md`。这是网页精简版，保留原记录的时间线和排错过程；原文中的时间、次数和编译数据属于当时记录，没有在此次网页导入中重新测量。\n\n[查看完整原始记录](./projects/heart-matrix/notes/03-project-log.md) · [阅读我的完整源码](./arduino-viewer.html?example=heart-matrix) · [看心跳效果](./projects/heart-matrix/index.html)\n\n## 第一个项目，要让它真的亮起来\n\n目标是用 Arduino UNO、8×32 MAX7219 点阵和五根杜邦线，显示一颗有心跳节奏的爱心。不额外安装第三方点阵库，先完成一个能观察、能解释的小作品。\n\n## 那天下午的记录\n\n| 时间 | 做了什么 | 观察到什么 |\n| --- | --- | --- |\n| 15:54 | 确认四片 8×8 点阵级联 | 确定五根线的接法 |\n| 16:04 | 第一版字符画和两帧大小动画 | 有反应，但不像爱心 |\n| 16:21 | 查看视频 | 看起来是两块亮斑，亮度在变 |\n| 16:32 | 改成图案固定、只调亮度 | 节奏更耐看，形状问题还在 |\n| 16:43 | 加每片 1/2/3/4 个点的测试 | 反馈为“4-3-2-1，都在最上面” |\n| 17:10 | 加 L 形测试 | 四个 L 看起来一致 |\n| 19:36 | 把爱心收窄到 12 列 | 比例更接近想要的效果 |\n| 19:41 | 提出“是不是代码里位置写错了” | 回头检查行列和寄存器映射 |\n| 19:53 | 修改 `show()` 的数据重组 | 原记录标记完成 |\n\n## 几次猜测，为什么没有解决问题\n\n第一种猜测是图案太暗、太小。把大小动画改成亮度动画，改善了观感，却没有解释两块奇怪亮斑。\n\n随后检查了模块是否装反、列方向是否相反、两块板之间的接缝是否影响效果。测试提供了一些线索，但“测试看起来正常”不等于所有映射关系都正确。\n\n转折点是重新问：**字符画里这一颗灯，到底会被写到哪个寄存器、哪个 bit？**\n\n## 最后改的是 `show()`\n\n画布 `canvas[32]` 按列保存。最终程序把列里的各个位取出来，重新组成当前模块需要的一行，然后写入对应寄存器。\n\n```cpp\nfor (uint8_t r = 0; r \u003c 8; r++) {\n  uint8_t bits = 0;\n  for (uint8_t b = 0; b \u003c 8; b++) {\n    if (canvas[c * 8 + b] & (1 \u003c\u003c r)) bits |= (1 \u003c\u003c b);\n  }\n  maxWrite(c, r + 1, bits);\n}\n```\n\n网页展示的最终 `.ino` 保留原始文件。完整版本还有方向开关、SPI 初始化、全亮自检和亮度控制。\n\n## 留下的经验\n\n- 先让简单效果工作，再慢慢加设计。\n- 一次只改一件事，记下预期和实际结果。\n- 调试图案要能区分你正在检查的变换。\n- 对比灯的位置，比凭整体观感猜原因更有效。\n- 对照片做分析时，留意透视和曝光带来的误差。\n\n## 重读原笔记时补上的说明\n\n全亮自检只说明显示链路在当时条件下能工作，不能证明供电余量与映射都正确。转置是行列互换，不等于旋转；某个 L 图案是否能检查转置，要看它的具体几何形状。\n\n原文“对角线可以确认转置”的建议也需要修正：主对角线转置后不变。下次可以从位置已知、转置后会变化的单点或组合标记开始，逐片建立坐标对应关系。\n\n## 原始记录中的数据\n\n| 项目 | 当时记录 |\n| --- | --- |\n| 总用时 | 约 4 小时 |\n| 上传次数 | 6 次 |\n| `show()` 重写 | 3 次 |\n| 编译占用 | 2076 B Flash / 290 B RAM |\n| 最终字符画 | 最宽 12 列、高 8 行，64 个亮点 |\n| 心跳周期 | 1100 ms |\n\n这些数字保留用于复盘。页面上的动画和封面是视觉示意，不是实时硬件画面。\n\n[继续读学习笔记](./blog.html#post/2026-11-25-heart-matrix-learning) · [遇到问题看排错笔记](./blog.html#post/2026-11-25-heart-matrix-troubleshooting)\n","posts/index.json":"[{\"slug\":\"2026-11-25-heart-matrix-troubleshooting\",\"title\":\"爱心点阵排错笔记：灯不对的时候看这里\",\"date\":\"2026-11-25\",\"parent\":\"2026-11-25-heart-matrix\",\"tags\":[\"Arduino\",\"MAX7219\",\"排错笔记\"],\"summary\":\"整理自我的 notes/02-troubleshooting.md：按现象检查供电、通信、方向、映射与上传问题。\",\"cover\":\"./projects/heart-matrix/preview.png\"},{\"slug\":\"2026-11-25-heart-matrix-learning\",\"title\":\"爱心点阵学习笔记：从一块点阵开始\",\"date\":\"2026-11-25\",\"parent\":\"2026-11-25-heart-matrix\",\"tags\":[\"Arduino\",\"MAX7219\",\"学习笔记\"],\"summary\":\"整理自我的 notes/01-learning-notes.md：五根线、SPI、寄存器、位运算与心跳动画。\",\"cover\":\"./projects/heart-matrix/preview.png\"},{\"slug\":\"2026-11-25-heart-matrix\",\"title\":\"我的第一个嵌入式项目：爱心点阵\",\"date\":\"2026-11-25\",\"tags\":[\"Arduino\",\"MAX7219\",\"项目记录\"],\"summary\":\"整理自我的 notes/03-project-log.md：保留时间线、走过的弯路，以及最后的行列映射修复。\",\"cover\":\"./projects/heart-matrix/preview.png\"}]"};
  async function readText(file) {
    if (location.protocol === 'file:') {
      const key = decodeURIComponent(file.replace(/^\.\//, ''));
      if (!Object.hasOwn(files, key)) throw new Error('找不到这份内容。');
      return files[key];
    }
    const response = await fetch(file, { cache: 'no-store' });
    if (!response.ok) throw new Error('内容读取失败（HTTP ' + response.status + '）。');
    return response.text();
  }
  window.SparkContent = Object.freeze({ readText, readJSON: async file => JSON.parse(await readText(file)) });
})();
